package com.bank.caching.core;

import com.bank.caching.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// A dataset with an expensive computation, demonstrating LAZY cache().
public class CachingDataset {
    private static final Logger log = Logger.getLogger(CachingDataset.class.getName());

    private final List<Txn> source;
    private boolean cacheRequested = false;     // set by cache() — just intent
    private Map<String, BigDecimal> cached = null; // filled on first action
    private int computeCount = 0;               // proves recomputation vs reuse

    public CachingDataset(List<Txn> source) { this.source = source; }

    // LAZY: only marks intent. No computation, no storage happens here.
    public CachingDataset cache() {
        this.cacheRequested = true;
        log.info("cache() called — intent registered ONLY (lazy, nothing computed/stored)");
        return this;
    }

    // The expensive computation (imagine heavy joins + aggregations).
    private Map<String, BigDecimal> expensiveCompute() {
        computeCount++;
        log.info(() -> "EXPENSIVE compute run #" + computeCount + " (full lineage executed)");
        Map<String, BigDecimal> totals = new HashMap<>();
        for (Txn t : source) totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        return totals;
    }

    // Internal: run or reuse depending on cache state.
    private Map<String, BigDecimal> materialize() {
        if (cacheRequested && cached != null) {
            log.info("reading from CACHE (no recomputation)");
            return cached;
        }
        Map<String, BigDecimal> result = expensiveCompute();
        if (cacheRequested) {
            cached = result; // store on first action that needs it
            log.info("cache MATERIALIZED on first action (computed + stored)");
        }
        return result;
    }

    // ACTION: count distinct accounts.
    public long countAccounts() { return materialize().size(); }

    // ACTION: get total for an account.
    public BigDecimal totalFor(String acct) {
        return materialize().getOrDefault(acct, BigDecimal.ZERO);
    }

    public int getComputeCount() { return computeCount; }
}
