package com.bank.caching;

import com.bank.caching.core.CachingDataset;
import com.bank.caching.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class CachingDemo {
    private static final Logger log = Logger.getLogger(CachingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new CachingLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Txn> txns = List.of(
            new Txn("SAV2001", new BigDecimal("1000")),
            new Txn("CUR3001", new BigDecimal("500")),
            new Txn("SAV2001", new BigDecimal("3000"))
        );

        CachingDataset ds = new CachingDataset(txns).cache();
        log.info("after cache(): computeCount = " + ds.getComputeCount() + " (still 0 → lazy!)");

        // First action: materializes the cache (computes + stores).
        log.info(() -> "accounts = " + ds.countAccounts());
        // Second and third actions: reuse the cache (no recompute).
        log.info(() -> "Rajesh total = " + ds.totalFor("SAV2001"));
        log.info(() -> "Priya total = " + ds.totalFor("CUR3001"));

        log.info(() -> "total expensive computations = " + ds.getComputeCount()
                + " (1, not 3 — caching worked)");
    }
}

